#include <iostream>
#include <iomanip>

int main() {
    // 1. Initializing a mutable char array and a const pointer to a string literal
    char buffer[20] = "Hello";
    const char* literalPtr = "World";

    std::cout << "Initial buffer: " << buffer << " (sizeof: " << sizeof(buffer) << ")\n";
    std::cout << "Literal pointer: " << literalPtr << "\n";

    // 2. Modifying mutable array elements
    buffer[0] = 'h';
    std::cout << "Modified buffer: " << buffer << "\n";

    // 3. Reading single word with setw to prevent buffer overflow
    char safeWord[8]; // Room for 7 characters + '\0'
    std::cin >> std::setw(8) >> safeWord;
    std::cout << "Read with setw(8): " << safeWord << "\n";

    // Clear trailing characters if any up to newline
    std::cin.ignore(100, '\n');

    // 4. Reading a full line using cin.getline
    char line[30];
    std::cin.getline(line, 30);
    std::cout << "Read with getline(30): " << line << "\n";

    return 0;
}
